import {useLayoutEffect,useRef} from 'react';
import {useOwnedAction} from '@/components/nyc-tron/ui/components/shell/useOwnedAction';

/** Document identity for controlled editor tools. Native handles remain outside UI state. */
export interface ScopedControlProps {scope?:string;revision?:string|number;disabledReason?:string}
export function controlIdentity(scope:string,revision:string|number){
 if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid control identity');
 return [scope,revision] as const;
}

/** Admit one host operation and invalidate handlers at the committed boundary. */
export function useScopedControl<P>(boundary:string,props:P,disabled=false){
 const action=useOwnedAction(boundary),pending=action.pending!==null;
 const committed=useRef<{boundary:string;props:P;disabled:boolean}|null>(null);
 const admitted=useRef<symbol|null>(null);
 useLayoutEffect(()=>{committed.current={boundary,props,disabled};});
 useLayoutEffect(()=>{admitted.current=null;},[boundary]);
 useLayoutEffect(()=>()=>{committed.current=null;},[]);
 const current=()=>{const p=committed.current;return p&&p.boundary===boundary&&!p.disabled&&!pending&&!admitted.current?p.props:null;};
 const run=(id:string,operation:(props:P,signal:AbortSignal)=>unknown|Promise<unknown>)=>{
  const p=current();if(!p)return;
  const token=Symbol(id);admitted.current=token;
  return action.run(id,signal=>operation(p,signal),undefined,{pendingForAsyncOnly:true}).finally(()=>{if(admitted.current===token)admitted.current=null;});
 };
 const cancel=()=>{if(committed.current?.boundary!==boundary)return false;admitted.current=null;action.cancel();return true;};
 return {current,run,cancel,pending,pendingId:action.pending,error:action.error};
}

import {ErrorMessage} from '@/components/nyc-tron/ui/components/feedback/ErrorMessage';
import {useScopedControl,controlIdentity,type ScopedControlProps} from '@/components/nyc-tron/ui/components/forge/inputs/useScopedControl';
import {Pressable,Text,TextInput,View,type ViewProps} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import type {FrameRate} from "@/components/nyc-tron/ui/components/forge/timebase";
import {formatTime,parseTime,supportsDropFrame,type TimeFormat} from "@/components/nyc-tron/ui/components/forge/timeline/time";
import {space,size} from '@/components/nyc-tron/ui/tokens';

/** Props for {@linkcode TimecodeDisplay}. */
export interface TimecodeDisplayProps extends Omit<ViewProps,"children">,ScopedControlProps {
  readonly frame:number;
  readonly rate:FrameRate;
  readonly format:TimeFormat;
  /** Shows the format switch. Keep the format in the host's preferences. */
  readonly onFormatChange?:(format:TimeFormat)=>void;
  /** SMPTE drop-frame labels; NTSC rates only. @default false */
  readonly dropFrame?:boolean;
  /** Enables the samples format. */
  readonly sampleRate?:number;
  /** Makes the time editable: one commit per accepted entry (Enter or blur). */
  readonly onCommit?:(frame:number)=>void;
  /** Highest frame a typed entry may reach. */
  readonly durationFrames?:number;
  /** @default "Current time" */
  readonly label?:string;
  className?:string;
  unstyled?:boolean;
}

const FORMAT_LABEL:Record<TimeFormat,string>={timecode:"Timecode",frames:"Frames",seconds:"Seconds",samples:"Samples"};
const HINT:Record<TimeFormat,string>={
  timecode:"Enter HH:MM:SS:FF",frames:"Enter a frame number",seconds:"Enter seconds, like 4.5",samples:"Enter HH:MM:SS.mmm",
};

/**
 * Time readout (D-08) in timecode (with drop-frame at 29.97/59.94), frames,
 * seconds or sample clock. With `onCommit` the readout is a field: typed time
 * in the current format commits once, out-of-range or malformed text is
 * rejected with the expected format, and the field keeps the draft.
 */
export function TimecodeDisplay({scope='TimecodeDisplay',revision=0,...props}:TimecodeDisplayProps){
 const owner=JSON.stringify([...controlIdentity(scope,revision),props.disabledReason,props.format,props.rate,props.durationFrames,props.dropFrame]);
 const guard=useScopedControl(owner,props,props.disabledReason!==undefined);
 return <TimecodeDisplayBody key={owner} {...props} actionError={guard.error} {...(guard.pending?{disabledReason:'Operation in progress'}:{})}
  {...(props.onCommit?{onCommit:(value:Parameters<NonNullable<TimecodeDisplayProps['onCommit']>>[0])=>guard.run('onCommit',host=>host.onCommit?.(value))}:{})}
  {...(props.onFormatChange?{onFormatChange:(value:Parameters<NonNullable<TimecodeDisplayProps['onFormatChange']>>[0])=>guard.current()?.onFormatChange?.(value)}:{})}/>;
}
function TimecodeDisplayBody({disabledReason,
  actionError=null,
  frame,rate,format,onFormatChange,dropFrame=false,sampleRate,onCommit,durationFrames,label="Current time",
  className,unstyled=false,testID,style,...rest
}:TimecodeDisplayProps&{actionError?:string|null}){
  if(dropFrame&&!supportsDropFrame(rate))throw new RangeError("Drop-frame timecode needs 29.97 or 59.94 fps");
  const [draft,store]=useLocalStore(()=>undefined as {text:string;error?:string}|undefined);
  const styled=!unstyled;
  const formats:TimeFormat[]=sampleRate===undefined?["timecode","frames","seconds"]:["timecode","frames","seconds","samples"];
  const current=formats.includes(format)?format:"timecode";
  const opts={dropFrame,...(sampleRate===undefined?{}:{sampleRate})};
  const shown=formatTime(Math.max(0,Math.round(frame)),rate,current,opts);
  // Reads the store, not the render's draft: Enter blurs the field, and the
  // blur's apply runs before a re-render, so it must see the cleared draft.
  const apply=()=>{
    const d=store.get();
    if(disabledReason!==undefined||!d||!onCommit)return;
    const f=parseTime(d.text,rate,current,opts);
    if(f===undefined||(durationFrames!==undefined&&f>durationFrames)){
      store.set({...d,error:f===undefined?HINT[current]+".":`Enter a time up to ${formatTime(durationFrames!,rate,current,opts)}.`});
      return;
    }
    store.set(undefined);
    if(f!==frame)onCommit(f);
  };
  const id=(s:string)=>testID?{testID:testID+"-"+s}:{};
  const text=joinClasses(styled&&"text-text text-lg font-semibold");
  return <View {...rest} {...(testID?{testID}:{})} {...{className:joinClasses("gap-1",className)}} style={[{flexDirection:"row",alignItems:"center",flexWrap:"wrap",gap:space[2]},style]}>
    <ErrorMessage message={actionError??undefined} unstyled={unstyled}/>
    {onCommit?<TextInput editable={disabledReason===undefined} maxLength={128} value={draft?.text??shown} onChangeText={t=>store.set({text:t})}
      onSubmitEditing={apply} onBlur={apply} selectTextOnFocus autoCorrect={false} autoCapitalize="none"
      accessibilityLabel={`${label}, ${FORMAT_LABEL[current]}`} accessibilityHint={HINT[current]} aria-invalid={Boolean(draft?.error)}
      {...id("input")}
      {...{className:joinClasses(text,styled&&"rounded-control border bg-surface-sunken px-2",
        styled&&(draft?.error?"border-danger":"border-border"))}}
      style={{minHeight:size.touch,minWidth:150,fontVariant:["tabular-nums"]}}/>
      :<Text selectable accessibilityLabel={`${label} ${shown}`} {...{className:text}} style={{fontVariant:["tabular-nums"]}}>{shown}</Text>}
    {onFormatChange?<Pressable disabled={disabledReason!==undefined} accessibilityRole="button" accessibilityLabel={`Time format: ${FORMAT_LABEL[current]}`}
      accessibilityHint="Switches to the next time format" {...id("format")}
      onPress={()=>{store.set(undefined);onFormatChange(formats[(formats.indexOf(current)+1)%formats.length]!);}}
      {...{className:joinClasses(styled&&"rounded-control border border-border px-3 focus-visible:ring-2 focus-visible:ring-focus")}}
      style={{minHeight:size.touch,justifyContent:"center"}}>
      <Text {...{className:joinClasses(styled&&"text-text-muted text-sm")}}>{FORMAT_LABEL[current]+(current==="timecode"&&dropFrame?" (drop-frame)":"")}</Text>
    </Pressable>:null}
    {draft?.error?<Text accessibilityLiveRegion="polite" {...{className:joinClasses(styled&&"text-danger text-xs")}} style={{flexBasis:"100%"}}>{draft.error}</Text>:null}
  </View>;
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

import { createStore } from "zustand/vanilla";

/** UI request state. Abort controllers stay in the owner's closure. */
export interface ActionState { readonly pending: string | null; readonly error: string | null }
export function createActionOwner(currentScope: () => string) {
  const store = createStore<ActionState>(() => ({ pending: null, error: null }));
  let active = false;
  let current: { readonly scope: string; readonly abort: AbortController } | null = null;
  function cancel() {
    const previous = current; current = null;
    previous?.abort.abort();
  }
  return {
    store,
    activate() { cancel(); active = true; store.setState({ pending: null, error: null }); },
    deactivate() { active = false; cancel(); },
    cancel() { cancel(); store.setState({ pending: null }); },
    async run<T>(id: string, operation: (signal: AbortSignal) => T | Promise<T>, consume?: (value: T) => void, options?: { pendingForAsyncOnly?: boolean }): Promise<boolean> {
      if (!active) return false;
      cancel();
      const request = { scope: currentScope(), abort: new AbortController() };
      current = request;
      const valid = () => active && current === request && request.scope === currentScope();
      if (options?.pendingForAsyncOnly) store.setState({ error: null });
      else store.setState({ pending: id, error: null });
      try {
        if (!valid()) return false;
        const result = operation(request.abort.signal);
        let value: T;
        if (options?.pendingForAsyncOnly) {
          if (result && typeof (result as Promise<T>).then === 'function') {
            // A synchronous acknowledgement or already-resolved promise must not
            // disable (and blur) the focused control between keyboard commands.
            let settled = false;
            const completion = Promise.resolve(result).then(value => { settled = true; return value; }, error => { settled = true; throw error; });
            void Promise.resolve().then(() => { if (!settled && valid()) store.setState({ pending: id, error: null }); });
            value = await completion;
          } else value = result as T;
        } else value = await result;
        if (!valid()) return false;
        consume?.(value);
        if (!valid()) return false;
        store.setState({ pending: null });
        return true;
      } catch (error) {
        if (!valid()) return false;
        store.setState({ pending: null, error: error instanceof Error ? error.message : String(error) });
        return false;
      } finally { if (current === request) current = null; }
    },
  };
}

import { useLayoutEffect, useRef } from "react";
import { useStore } from "zustand";
import { createActionOwner } from "@/components/nyc-tron/ui/components/shell/action-owner";

/** Cancel stale requests at the committed document boundary, before new controls accept input. */
export function useOwnedAction(scope: string) {
  const committed = useRef(scope);
  const ref = useRef<ReturnType<typeof createActionOwner> | null>(null);
  ref.current ??= createActionOwner(() => committed.current);
  const owner = ref.current;
  useLayoutEffect(() => {
    committed.current = scope;
    owner.activate();
    return () => owner.deactivate();
  }, [owner, scope]);
  const state = useStore(owner.store, value => value);
  const run: typeof owner.run = (id, operation, consume, options) => committed.current === scope ? owner.run(id, operation, consume, options) : Promise.resolve(false);
  return { ...state, run, cancel: owner.cancel };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

